/bin/bash -lc 'set -eu
case_copy=$(mktemp -d "$PWD/.contract-check.XXXXXXXX")
trap '"'python3 -c \"import shutil, sys; shutil.rmtree(sys.argv[1])\" \""'$case_copy"'"' EXIT
cp -R release \""'$case_copy/release"
archive="$PWD/vendor/hono-4.13.19.tgz"
export npm_config_cache="$case_copy/npm-cache"
export npm_config_update_notifier=false
cd "$case_copy/release"
npm install --offline --ignore-scripts --no-audit --no-fund "$archive"
npm test
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import app from './app.mjs';

const pkg = JSON.parse(await readFile('node_modules/hono/package.json', 'utf8'));
assert.equal(pkg.version, '4.13.19');
console.log('Hono', pkg.version, '| Node', process.version);

const cases = [
  ['a7, рабочая сессия', 'a7', 'day', 200, {id: 'a7', title: 'Harbor'}, 'dispatch,session,read'],
  ['a7, без сессии', 'a7', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['отсутствующая карточка, рабочая сессия', 'missing-card', 'day', 404, {error: 'not_found'}, 'dispatch,session,read'],
  ['b4, рабочая сессия', 'b4', 'day', 502, {error: 'invalid_record'}, 'dispatch,session,read,error'],
  ['b4, без сессии', 'b4', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['отсутствующая карточка, без сессии', 'missing-card', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
];
for (const [label, id, shift, status, body, steps] of cases) {
  const request = new Request('http://localhost/desk/' + id, {
    headers: shift === undefined ? {} : {'x-shift': shift},
  });
  const response = await app.request(request);
  assert.ok(response instanceof Response);
  const observed = {
    status: response.status,
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  console.log(label, JSON.stringify(observed));
  assert.equal(response.headers.get('content-type')?.split(';', 1)[0], 'application/json');
  assert.deepEqual(observed, {status, body, steps});
}
NODE"

